import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.BXmxXpv-.js";const u=JSON.parse('{"title":"智能计算系统实验室","titleTemplate":"电子科技大学","description":"电子科技大学智能计算系统实验室，开展智能计算、物联网、无线嵌入式系统、边缘智能、智能感知与系统安全研究。","frontmatter":{"layout":"home","title":"智能计算系统实验室","titleTemplate":"电子科技大学","description":"电子科技大学智能计算系统实验室，开展智能计算、物联网、无线嵌入式系统、边缘智能、智能感知与系统安全研究。","hero":{"name":"智能计算系统实验室","tagline":"面向大规模感知的低成本计算与通信","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md","lastUpdated":1793675049000}'),n={name:"zh/index.md"};function d(i,t,h,s,l,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="我们的目标" tabindex="-1">我们的目标 <a class="header-anchor" href="#我们的目标" aria-label="Permalink to &quot;我们的目标&quot;">​</a></h2><p>我们希望让感知网络以更低的成本覆盖更广的世界，持续获取人类生活、生产与自然环境中的有效信息。从温度、光照、振动到声音、图像与视频，我们研究如何降低感知终端的硬件、计算、通信和供能负担，通过端—边—云协同，帮助人们更完整地理解真实世界的状态与变化，为预测、决策和行动提供可靠依据。</p><p><a href="/zh/research#研究目标">了解研究目标与技术路径</a></p><h2 id="最新动态" tabindex="-1">最新动态 <a class="header-anchor" href="#最新动态" aria-label="Permalink to &quot;最新动态&quot;">​</a></h2><h3 id="_2026-年-7-月" tabindex="-1">2026 年 7 月 <a class="header-anchor" href="#_2026-年-7-月" aria-label="Permalink to &quot;2026 年 7 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">Hades: A Hardware-Resident Substrate for Energy Admission in Intermittent Computing</a></strong> 被 <strong>MICRO 2026</strong> 接收。这是来自中国西部高校的首篇 MICRO 论文。</li><li>祝贺团队论文 <strong><a href="/zh/publication">Speak and Be Known: Authenticating Users via Ear Canal Deformation on Earbuds</a></strong> 于 <strong>TMC 2026</strong> 发表。</li></ul><h3 id="_2026-年-5-月" tabindex="-1">2026 年 5 月 <a class="header-anchor" href="#_2026-年-5-月" aria-label="Permalink to &quot;2026 年 5 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">μMan: Towards Device-Agnostic Power Management for Battery-free IoT</a></strong> 被 <strong>SenSys 2026</strong> 接收。</li></ul><h3 id="_2026-年-3-月" tabindex="-1">2026 年 3 月 <a class="header-anchor" href="#_2026-年-3-月" aria-label="Permalink to &quot;2026 年 3 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">Remote Intermittency Control for RF-powered Devices via Backscatter Communication</a></strong> 于 <strong>TMC 2026</strong> 发表。</li></ul><p>... <a href="/zh/news">查看全部动态</a></p><h2 id="团队简介" tabindex="-1">团队简介 <a class="header-anchor" href="#团队简介" aria-label="Permalink to &quot;团队简介&quot;">​</a></h2><p>智能计算系统实验室隶属于电子科技大学计算机科学与工程学院。团队成立于 2018 年 1 月，面向无线系统与安全、无源系统、RFID 技术、网络与系统安全、智能信息处理、数据挖掘与推荐、智能视频分析等方向开展基础研究与系统研发。实验室关注智能计算与物理世界的深度融合，结合无源感知、边缘智能、无线嵌入式系统和多模态信息处理，探索面向具身智能的感知、通信与计算支撑技术。研究团队包括教授博导 1 人、副教授 1 人，硕博研究生近 30 人。近五年，团队承担了多项国家自然科学基金、国家重点研发计划、国家科技支撑计划等项目。</p><p>团队在无源无线感知物联网系统、无线嵌入式系统和智能信息处理等方面取得了系列研究成果，构建了面向结构健康监测、可穿戴医疗设备、远程健康监护等场景的实际系统与应用示范。在 ACM/IEEE Transactions 期刊和国际顶级学术会议上发表论文 120 余篇。实验室具备较完整的研发设备、系统软件、应用软件和设计开发工具，形成了覆盖感知前端设计、通信协议与系统、智能信息处理、云端系统和网络安全的研发链条。</p><h2 id="主要研究领域及方向" tabindex="-1">主要研究领域及方向 <a class="header-anchor" href="#主要研究领域及方向" aria-label="Permalink to &quot;主要研究领域及方向&quot;">​</a></h2><p><a href="/zh/research">深入了解实验室研究方向。</a></p><ul><li><strong><a href="/zh/research#微计算">微计算</a></strong>：直接外设访问、可组合控制与邻近处理器共享，让轻量感知任务用更低开销执行。</li><li><strong><a href="/zh/research#微通信">微通信</a></strong>：协同参考信号与模拟、混合信号处理，降低无线收发负担。</li><li><strong><a href="/zh/research#能量管理">能量管理</a></strong>：网关协同管理与端侧硬件准入，让环境能量支撑有效任务。</li><li><strong><a href="/zh/research#复杂感知">复杂感知</a></strong>：探索按任务组织音视频信息、结构化视觉证据与可配置执行。</li></ul><p><a href="/zh/research#安全与信息应用">安全与信息应用</a>贯穿上述研究，连接隐私防护、可信交互与高效数据分析。</p><h2 id="代表性科研项目" tabindex="-1">代表性科研项目 <a class="header-anchor" href="#代表性科研项目" aria-label="Permalink to &quot;代表性科研项目&quot;">​</a></h2><p><a href="/zh/projects">查看代表性科研项目页。</a></p><table tabindex="0"><thead><tr><th>项目类型</th><th>项目名称</th><th>执行期间</th></tr></thead><tbody><tr><td>国家自然科学基金面上项目</td><td>物联网无线总线理论与关键技术研究</td><td>2026-2029</td></tr><tr><td>横向项目</td><td>“云-边-端”智能精铣刨系统集成技术研究与开发</td><td>2026-2028</td></tr><tr><td>国家自然科学基金面上项目</td><td>云边融合的分布式大规模图数据流计算方法</td><td>2025-2028</td></tr><tr><td>横向项目</td><td>基于动力学的胸外心脏按压机制研究与精准复苏</td><td>2024-2025</td></tr><tr><td>自主研发项目</td><td>长距离超低功耗无线通信芯片研究</td><td>2023-2026</td></tr><tr><td>国家自然科学基金面上项目</td><td>基于多组学时序性图神经网络的血栓-炎症模型在急性主动脉夹层早期诊断和危险分层中的机制研究与转化</td><td>2023-2025</td></tr><tr><td>国家自然科学基金联合基金重点项目</td><td>安全攸关的航空智能制造威胁监测和动态自适应防御研究</td><td>2022-2025</td></tr><tr><td>国家重点研发计划</td><td>隐私数据按需脱敏与评估关键技术研究</td><td>2021-2024</td></tr></tbody></table>',21)])])}const f=a(n,[["render",d]]);export{u as __pageData,f as default};
